package hu.synostream.android;
import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.os.Build;
final class LanguageUi {
 static void show(MainActivity a){String[] labels={a.getString(R.string.language_hu),a.getString(R.string.language_en)};AlertDialog dialog=new AlertDialog.Builder(a).setTitle(a.getString(R.string.language_title)).setSingleChoiceItems(labels,"en".equals(UiLocale.language(a))?1:0,(d,index)->{String language=index==1?"en":"hu";if(language.equals(UiLocale.language(a))){d.dismiss();return;}if(!UiLocale.save(a,language)){a.toast(a.getString(R.string.language_unsaved));return;}try{refreshNotifications(a);}catch(SecurityException permissionChanged){/* Locale persistence does not depend on notification permission. */}d.dismiss();a.recreate();}).setNegativeButton(a.getString(R.string.msg_cancel_b3e118),null).create();a.ownDialog(dialog);dialog.show();}
 static void refreshNotifications(Context source){Context c=UiText.context(source);NotificationManager manager=c.getSystemService(NotificationManager.class);for(String id:new String[]{"scan","stream"}){NotificationChannel channel=manager.getNotificationChannel(id);if(channel!=null){channel.setName(c.getString(id.equals("scan")?R.string.msg_library_scan_afed43:R.string.msg_video_streaming_53c860));manager.createNotificationChannel(channel);}}if(Build.VERSION.SDK_INT>=33&&c.checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)return;for(android.service.notification.StatusBarNotification status:manager.getActiveNotifications()){Notification old=status.getNotification();boolean scan="scan".equals(old.getChannelId()),stream="stream".equals(old.getChannelId());if(!scan&&!stream)continue;Notification.Builder builder=Notification.Builder.recoverBuilder(c,old).setContentTitle(c.getString(scan?R.string.msg_synostream_library_scan_548fac:R.string.stream_notification_title)).setContentText(UiText.message(c,old.extras.getString(Notification.EXTRA_TEXT,"")));if(old.actions!=null&&old.actions.length>0){Notification.Action[] actions=new Notification.Action[old.actions.length];for(int n=0;n<actions.length;n++)actions[n]=new Notification.Action.Builder(old.actions[n].getIcon(),c.getString(scan?R.string.msg_cancel_533cb7:R.string.msg_stop_edfff6),old.actions[n].actionIntent).build();builder.setActions(actions);}manager.notify(status.getTag(),status.getId(),builder.build());}}
 private LanguageUi(){}
}
